#include "test.hpp"
#include "mspa/mspa.hpp"
using namespace mspa;
int main(){AgentPsychState a{};a.id={WorldId(1),1};a.personality.persistence=0.2f;a.personality.curiosity=0.9f;Proposition p{};p.predicate=PredicateId(1);p.name_space=NamespaceId(1);BeliefEvidence e{};e.proposition=p;e.strength=0.8f;e.source_trust=1.0f;e.observed_at=PsychTime(10);auto u=BeliefSystem{}.update(a,e);require(u&&u.value_if()->created,"belief created");float before=a.beliefs[0].certainty;require(BeliefSystem{}.update(a,e),"belief reinforce update");require(a.beliefs[0].certainty>before,"belief certainty rises");BeliefEvidence contrary=e;contrary.proposition.positive=false;contrary.strength=1.0f;for(int i=0;i<4;++i)require(BeliefSystem{}.update(a,contrary),"contradiction processed");require(!a.beliefs[0].proposition.positive,"belief can flip under strong contradiction");RegistryBuilder rb;PredicateSchema s{};s.id=PredicateId(1);s.name_space=NamespaceId(1);s.default_relevance=0.8f;s.default_consequence=-0.8f;s.intentionality=1.0f;s.agency_role="actor";s.appraisal_hints={"threat"};require(rb.add_predicate(s),"schema");p.arguments.push_back({"actor","enemy"});auto app=AppraisalEngine{}.evaluate(a,p,rb.publish());require(app.relevance>0.5f&&app.consequence<0,"appraisal");EmotionSystem{}.apply(a,app,PsychTime(12));require(!a.emotions.empty(),"emotion generated");MoodSystem{}.absorb_emotions(a,PsychTime(12));require(a.mood.activation>0,"mood absorbs emotion");GoalSystem goals;auto gid=goals.add(a,ConceptId(5),0.8f,0.9f,PsychTime(12));require(gid,"goal add");require(goals.set_status(a,*gid.value_if(),GoalStatus::Suspended,PsychTime(13)),"goal suspend");MemorySystem mem;auto mid=mem.remember(a,p,0.9f,PsychTime(2),-0.7f);require(mid,"memory add");require(mem.reactivate(a,*mid.value_if(),PsychTime(14)),"memory reactivate");RelationshipSystem rel;RelationshipDelta d{};d.trust=0.4f;require(rel.adjust(a,{WorldId(1),2},d),"relationship adjust");require(rel.find(a,{WorldId(1),2})->trust==0.4f,"relationship directional state");LearningReport lr{};lr.action=ActionTypeId(7);lr.context_tags={"night","rain"};lr.outcome_tags={"safe"};lr.success=true;lr.now=PsychTime(15);require(LearningSystem{}.report(a,lr),"contextual learning");require(LearningSystem{}.expected_outcome(a,ActionTypeId(7),{"rain","night"},"safe")>0.5f,"context tags canonicalized");std::cout<<"psychology ok\n";}
